// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.eclipse.rdf4j.sail.lmdb.LmdbPackedRuleDifferentialSupport.check;

import java.io.File;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * A UNION of a VALUES branch holding language-tagged literals with a stored predicate whose objects LMDB proves to be
 * language-free must not let the packed planner prove {@code langMatches(lang(?o), "*")} false or {@code lang(?o) = ""}
 * true: the VALUES branch's language knowledge is either recorded precisely or stays unknown, and unknown widened with
 * known is unknown.
 */
class LmdbUnionLanguageFactsTest {

	private static final String DATA = """
			@prefix : <urn:t:> .
			:s1 :p "x" .
			:s2 :p "y" .
			""";

	@Test
	void subSelectUnionLangEmptyFilter(@TempDir File dir) throws Exception {
		check(dir, DATA,
				"SELECT ?o WHERE { { SELECT ?o WHERE { { VALUES ?o { \"a\"@en } } UNION { ?s :p ?o } } } "
						+ "FILTER(lang(?o) = \"\") }",
				List.of("o=\"x\"", "o=\"y\""));
	}

	@Test
	void subSelectUnionLangMatchesStar(@TempDir File dir) throws Exception {
		check(dir, DATA,
				"SELECT ?o WHERE { { SELECT ?o WHERE { { VALUES ?o { \"a\"@en } } UNION { ?s :p ?o } } } "
						+ "FILTER(langMatches(lang(?o), \"*\")) }",
				List.of("o=\"a\"@en"));
	}

	@Test
	void directUnionLangMatchesStar(@TempDir File dir) throws Exception {
		check(dir, DATA,
				"SELECT ?o WHERE { { VALUES ?o { \"a\"@en } } UNION { ?s :p ?o } FILTER(langMatches(lang(?o), \"*\")) }",
				List.of("o=\"a\"@en"));
	}

	@Test
	void directUnionLangEmptyFilter(@TempDir File dir) throws Exception {
		check(dir, DATA, "SELECT ?o WHERE { { VALUES ?o { \"a\"@en } } UNION { ?s :p ?o } FILTER(lang(?o) = \"\") }",
				List.of("o=\"x\"", "o=\"y\""));
	}

	@Test
	void directUnionMixedValuesLangMatchesStar(@TempDir File dir) throws Exception {
		check(dir, DATA,
				"SELECT ?o WHERE { { VALUES ?o { \"a\"@en \"b\" } } UNION { ?s :p ?o } FILTER(langMatches(lang(?o), \"*\")) }",
				List.of("o=\"a\"@en"));
	}

	@Test
	void unionOfTwoStoredPredicatesWithDifferentLanguageProofs(@TempDir File dir) throws Exception {
		String data = DATA + ":s3 :q \"a\"@en .\n:s4 :q \"b\" .\n";
		check(dir, data, "SELECT ?o WHERE { { ?s :p ?o } UNION { ?s :q ?o } FILTER(langMatches(lang(?o), \"*\")) }",
				List.of("o=\"a\"@en"));
	}
}
